import json
from pathlib import Path
P=Path(__file__).resolve().parents[1];L=P/'labyrinth'
def node(i,kind,tier,title,statement,**kw):
    n={'id':i,'kind':kind,'tier':tier,'title':title,'statement':statement,'status':'open' if kind=='conjecture' else 'refuted' if kind=='deadend' else 'established' if kind=='theorem' else 'computed','where':['../ROUTES.md'],'links':[],**kw}
