(L/'frontier.json').write_text(json.dumps({'meta':{'size_name':'test batch','value_name':'rank-check outcome'},'sizes':[]},indent=2))
(L/'sota.json').write_text(json.dumps({'about':'Task-local handoff, not canonical project SOTA','groups':['Probability'],'entries':[{'id':n['id'],'group':'Probability','cls':n['title'],'result':n['statement'],'status':str(n['tier'])+' '+n['status']+' unreviewed','kind':'conjecture' if n['kind']=='conjecture' else 'refuted' if n['kind']=='deadend' else 'computed' if n['kind']=='evidence' else 'proved' if n['kind']=='theorem' else 'partial','refs':n['where'],'lit':[],'updated':'2026-11-14','previous':[]} for n in nodes]},indent=2))
